//! Cross-check harness: run the kernels over inputs generated by
//! `/tmp/opencode/kern_check/mkkern.py` and dump results as `rust_*.txt`
//! for comparison against the numpy `ref_*.txt` files.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};

use qwen3_5_397b_in_rust::model::kernels::{attention_forward, conv1d_silu, delta_net_autoregressive, gemm, gemv, moe_ffn, rms_norm, rms_norm_per_head, rope_multi_imrope, softmax_topk, swiglu, RopeConfig};
use qwen3_5_397b_in_rust::gguf::GGmlType;

fn read_f32_file(path: &Path, n: usize) -> Vec<f32> {
    let data = fs::read(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    assert_eq!(data.len(), n * 4, "{}: expected {n} f32 values, got {} bytes", path.display(), data.len());
    data.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect()
}

fn write_txt(path: &Path, vals: &[f32]) {
    let mut s = String::new();
    for v in vals {
        s.push_str(&format!("{v:.9e}\n"));
    }
    fs::write(path, s).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
}

fn ty_from_name(name: &str) -> GGmlType {
    match name {
        "Q8_0" => GGmlType::Q8_0,
        "Q4_K" => GGmlType::Q4_K,
        "Q5_K" => GGmlType::Q5_K,
        "Q6_K" => GGmlType::Q6_K,
        "F32" => GGmlType::F32,
        other => panic!("unknown type {other}"),
    }
}

fn main() {
    let dir = PathBuf::from(env::args().nth(1).unwrap_or_else(|| "/tmp/opencode/kern_check".to_string()));
    let spec = fs::read_to_string(dir.join("spec.txt")).expect("read spec.txt");
    for (lineno, line) in spec.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "rms" => {
                let id = f[1];
                let n: usize = f[2].parse().unwrap();
                let eps: f32 = f[3].parse().unwrap();
                let x = read_f32_file(&dir.join(format!("rms_{id}.bin")), n);
                let w = read_f32_file(&dir.join(format!("rms_{id}_w.bin")), n);
                let out = rms_norm(&x, &w, eps);
                write_txt(&dir.join(format!("rust_rms_{id}.txt")), &out);
            }
            "gemv" => {
                let ty = ty_from_name(f[1]);
                let n_in: usize = f[2].parse().unwrap();
                let n_out: usize = f[3].parse().unwrap();
                let w = fs::read(dir.join(format!("gemv_{}_w.bin", f[1]))).expect("read weight file");
                let x = read_f32_file(&dir.join(f[4]), n_in);
                let out = gemv(ty, &w, n_in, n_out, &x).expect("gemv");
                assert_eq!(out.len(), n_out);
                write_txt(&dir.join(format!("rust_gemv_{}.txt", f[1])), &out);
            }
            "gemm" => {
                let ty = ty_from_name(f[1]);
                let n_in: usize = f[2].parse().unwrap();
                let n_out: usize = f[3].parse().unwrap();
                let n_batch: usize = f[4].parse().unwrap();
                let w = fs::read(dir.join(format!("gemm_{}_w.bin", f[1]))).expect("read weight file");
                let x = read_f32_file(&dir.join(f[5]), n_in * n_batch);
                let out = gemm(ty, &w, n_in, n_out, n_batch, &x).expect("gemm");
                assert_eq!(out.len(), n_out * n_batch);
                write_txt(&dir.join(format!("rust_gemm_{}.txt", f[1])), &out);
            }
            "attn" => {
                let id = f[1];
                let n_heads: usize = f[2].parse().unwrap();
                let n_kv_heads: usize = f[3].parse().unwrap();
                let head_dim: usize = f[4].parse().unwrap();
                let n_q: usize = f[5].parse().unwrap();
                let n_kv: usize = f[6].parse().unwrap();
                let causal: bool = f[7].parse::<u8>().unwrap() != 0;
                let scale = 1.0 / (head_dim as f32).sqrt();
                let q = read_f32_file(&dir.join(format!("attn_{id}_q.bin")), n_q * n_heads * head_dim);
                let k = read_f32_file(&dir.join(format!("attn_{id}_k.bin")), n_kv * n_kv_heads * head_dim);
                let v = read_f32_file(&dir.join(format!("attn_{id}_v.bin")), n_kv * n_kv_heads * head_dim);
                let out = attention_forward(&q, &k, &v, n_heads, n_kv_heads, head_dim, n_q, n_kv, scale, causal);
                assert_eq!(out.len(), n_q * n_heads * head_dim);
                write_txt(&dir.join(format!("rust_attn_{id}.txt")), &out);
            }
            "delta" => {
                let id: usize = f[1].parse().unwrap();
                let s_k: usize = f[2].parse().unwrap();
                let s_v: usize = f[3].parse().unwrap();
                let n_heads: usize = f[4].parse().unwrap();
                let n_steps: usize = f[5].parse().unwrap();
                let eps = 1e-6f32;
                let mut state = vec![0.0f32; s_v * s_v * n_heads];
                for step in 0..n_steps {
                    let q = read_f32_file(&dir.join(format!("dn_{id}_s{step}_q.bin")), s_k * n_heads);
                    let k = read_f32_file(&dir.join(format!("dn_{id}_s{step}_k.bin")), s_k * n_heads);
                    let v = read_f32_file(&dir.join(format!("dn_{id}_s{step}_v.bin")), s_v * n_heads);
                    let g = read_f32_file(&dir.join(format!("dn_{id}_s{step}_g.bin")), n_heads);
                    let beta = read_f32_file(&dir.join(format!("dn_{id}_s{step}_beta.bin")), n_heads);
                    let out = delta_net_autoregressive(&q, &k, &v, &g, &beta, &mut state, s_k, s_v, n_heads, eps);
                    assert_eq!(out.len(), s_v * n_heads);
                    write_txt(&dir.join(format!("rust_dn_{id}_s{step}.txt")), &out);
                }
            }
            "rope" => {
                let id = f[1];
                let ne0: usize = f[2].parse().unwrap();
                let n_dims: usize = f[3].parse().unwrap();
                let sections: [i32; 4] = [
                    f[4].parse().unwrap(),
                    f[5].parse().unwrap(),
                    f[6].parse().unwrap(),
                    f[7].parse().unwrap(),
                ];
                let pos: [i32; 4] = [
                    f[8].parse().unwrap(),
                    f[9].parse().unwrap(),
                    f[10].parse().unwrap(),
                    f[11].parse().unwrap(),
                ];
                let n_ctx_orig: usize = f[12].parse().unwrap();
                let cfg = RopeConfig {
                    freq_base: f[13].parse().unwrap(),
                    freq_scale: f[14].parse().unwrap(),
                    ext_factor: f[15].parse().unwrap(),
                    attn_factor: f[16].parse().unwrap(),
                    ..Default::default()
                };
                let x = read_f32_file(&dir.join(format!("rope_{id}.bin")), ne0);
                let out = rope_multi_imrope(&x, pos, n_dims, sections, n_ctx_orig, &cfg);
                assert_eq!(out.len(), ne0);
                write_txt(&dir.join(format!("rust_rope_{id}.txt")), &out);
            }
            "swiglu" => {
                let id = f[1];
                let n: usize = f[2].parse().unwrap();
                let gate = read_f32_file(&dir.join(format!("swiglu_{id}_gate.bin")), n);
                let up = read_f32_file(&dir.join(format!("swiglu_{id}_up.bin")), n);
                let out = swiglu(&gate, &up);
                assert_eq!(out.len(), n);
                write_txt(&dir.join(format!("rust_swiglu_{id}.txt")), &out);
            }
            "rph" => {
                let id = f[1];
                let n: usize = f[2].parse().unwrap();
                let head_size: usize = f[3].parse().unwrap();
                let x = read_f32_file(&dir.join(format!("rph_{id}.bin")), n);
                let w = read_f32_file(&dir.join(format!("rph_{id}_w.bin")), head_size);
                let out = rms_norm_per_head(&x, &w, head_size, 1e-6);
                assert_eq!(out.len(), n);
                write_txt(&dir.join(format!("rust_rph_{id}.txt")), &out);
            }
            "topk" => {
                let id = f[1];
                let n_experts: usize = f[2].parse().unwrap();
                let k: usize = f[3].parse().unwrap();
                let logits = read_f32_file(&dir.join(format!("topk_{id}.bin")), n_experts);
                let (weights, indices) = softmax_topk(&logits, k);
                assert_eq!(weights.len(), k);
                assert_eq!(indices.len(), k);
                // Save weights as txt
                write_txt(&dir.join(format!("rust_topk_{id}_w.txt")), &weights);
                // Save indices as f32 txt
                let idx_f32: Vec<f32> = indices.iter().map(|&i| i as f32).collect();
                write_txt(&dir.join(format!("rust_topk_{id}_i.txt")), &idx_f32);
            }
            "conv" => {
                let id = f[1];
                let channels: usize = f[2].parse().unwrap();
                let kernel_size: usize = f[3].parse().unwrap();
                let seq_len: usize = f[4].parse().unwrap();
                let inp = read_f32_file(&dir.join(format!("conv_{id}_inp.bin")), channels * seq_len);
                let krn = read_f32_file(&dir.join(format!("conv_{id}_krn.bin")), channels * kernel_size);
                let pad = kernel_size - 1;
                let st = read_f32_file(&dir.join(format!("conv_{id}_st.bin")), channels * pad);
                let (out, state_out) = conv1d_silu(&inp, &krn, &st, channels, seq_len, kernel_size);
                assert_eq!(out.len(), channels * seq_len);
                assert_eq!(state_out.len(), channels * pad);
                write_txt(&dir.join(format!("rust_conv_{id}_out.txt")), &out);
                write_txt(&dir.join(format!("rust_conv_{id}_st.txt")), &state_out);
            }
            "moe" => {
                let id = f[1];
                let n_embd: usize = f[2].parse().unwrap();
                let n_ff: usize = f[3].parse().unwrap();
                let n_expert: usize = f[4].parse().unwrap();
                let n_expert_used: usize = f[5].parse().unwrap();
                let n_tokens: usize = f[6].parse().unwrap();
                let inp = read_f32_file(&dir.join(format!("moe_{id}_inp.bin")), n_tokens * n_embd);
                let rw = read_f32_file(&dir.join(format!("moe_{id}_rw.bin")), n_expert * n_embd);
                let guw = read_f32_file(&dir.join(format!("moe_{id}_guw.bin")), n_expert * 2 * n_ff * n_embd);
                let dw = read_f32_file(&dir.join(format!("moe_{id}_dw.bin")), n_expert * n_embd * n_ff);
                let out = moe_ffn(&inp, &rw, &guw, &dw, n_embd, n_ff, n_expert, n_expert_used, n_tokens);
                assert_eq!(out.len(), n_tokens * n_embd);
                write_txt(&dir.join(format!("rust_moe_{id}.txt")), &out);
            }
            other => panic!("spec line {}: unknown directive {other}", lineno + 1),
        }
    }
    println!("kern_check wrote rust_* outputs to {}", dir.display());
}
